// Components of Disk Access Time (T_access)
float T_seek;           // Time to position R/W head over cylinder
float T_latency;        // Time for desired sector to rotate under head
float T_transfer;       // Time to transfer data block
float total_T_access = T_seek + T_latency + T_transfer;

// Calculating Average Rotational Latency
float RPM = 7200.0;
float sec_per_rev = 60.0 / RPM;
// Average latency is half a revolution
float avg_latency_sec = 0.5 * sec_per_rev;

// I/O Operations Per Second (IOPS)
long total_io_requests = 500000;
float test_time_sec = 5.0;
float calculated_iops = total_io_requests / test_time_sec;

// Disk Throughput (Bandwidth, MB/s)
long data_transferred_MB = 1024;
float throughput_MB_s = data_transferred_MB / test_time_sec;

// I/O Pattern Impact (Code Structure Concept)
void sequential_read(int start_block, int count) {
    // Minimize T_seek
    for (int i = 0; i < count; i++) {
        read_block(start_block + i);
    }
}
void random_read(int* block_list, int count) {
    // Maximize T_seek/T_latency impact
    for (int i = 0; i < count; i++) {
        read_block(block_list[i]); // Requires new seek/latency per call
    }
}
